import sys

from counting import count_words


def main(argv):
    with open(argv[0], encoding='utf-8') as handle:
        counts = count_words(handle.read())
    for word, number in counts.most_common(3):
        print(f'{word} {number}')


if __name__ == '__main__':
    main(sys.argv[1:])

